CREATE TABLE IF NOT EXISTS platform_setting (setting_key VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS platform_migration (version VARCHAR(80) PRIMARY KEY, applied_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS trade_delivery (order_id BIGINT PRIMARY KEY, nonce VARCHAR(36) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, attempts INT NOT NULL DEFAULT 0, verified_at TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS trade_subscription (id BIGINT AUTO_INCREMENT PRIMARY KEY, buyer_id BIGINT NOT NULL, listing_id BIGINT NOT NULL, buyer_name VARCHAR(100) NOT NULL, quantity DECIMAL(13,3) NOT NULL, unit VARCHAR(16) NOT NULL, max_price DECIMAL(12,2) NOT NULL, interval_days INT NOT NULL, next_date DATE NOT NULL, delivery_address VARCHAR(500) NOT NULL, status VARCHAR(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS trade_occurrence (id BIGINT AUTO_INCREMENT PRIMARY KEY, subscription_id BIGINT NOT NULL, delivery_date DATE NOT NULL, outcome VARCHAR(30) NOT NULL, detail VARCHAR(255), order_id BIGINT, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT uq_subscription_day UNIQUE(subscription_id,delivery_date));
CREATE TABLE IF NOT EXISTS trade_bulk (id BIGINT AUTO_INCREMENT PRIMARY KEY, buyer_id BIGINT NOT NULL, product_name VARCHAR(120) NOT NULL, quantity DECIMAL(13,3) NOT NULL, unit VARCHAR(16) NOT NULL, budget DECIMAL(12,2) NOT NULL, required_date DATE NOT NULL, district VARCHAR(100) NOT NULL, note VARCHAR(500), status VARCHAR(16) NOT NULL, accepted_quote_id BIGINT, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS trade_quote (id BIGINT AUTO_INCREMENT PRIMARY KEY, bulk_id BIGINT NOT NULL, seller_id BIGINT NOT NULL, listing_id BIGINT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, valid_until DATE NOT NULL, note VARCHAR(500), status VARCHAR(16) NOT NULL, order_id BIGINT, created_at TIMESTAMP(6) NOT NULL, CONSTRAINT uq_bulk_seller_listing UNIQUE(bulk_id,seller_id,listing_id));
CREATE TABLE IF NOT EXISTS trade_return (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, buyer_id BIGINT NOT NULL, seller_id BIGINT NOT NULL, remedy VARCHAR(20) NOT NULL, reason VARCHAR(1000) NOT NULL, evidence VARCHAR(500), status VARCHAR(24) NOT NULL, admin_note VARCHAR(1000), refund_amount DECIMAL(12,2), resolution_reference VARCHAR(120), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS farm_material (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, category VARCHAR(40) NOT NULL, unit VARCHAR(16) NOT NULL, quantity DECIMAL(13,3) NOT NULL, low_threshold DECIMAL(13,3) NOT NULL, unit_cost DECIMAL(12,2), created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE IF NOT EXISTS farm_material_movement (id BIGINT AUTO_INCREMENT PRIMARY KEY, material_id BIGINT NOT NULL, owner_id BIGINT NOT NULL, entry_id BIGINT, quantity DECIMAL(13,3) NOT NULL, reason VARCHAR(120) NOT NULL, request_key VARCHAR(80) UNIQUE, created_at TIMESTAMP(6) NOT NULL);
